                dp[i][sum] = true;
                continue;
            }
            if(i==0){
                dp[i][sum] = (sum==arr[i]);
                continue;
            }
            bool t = false;
            if(arr[i] <= sum) t = dp[i-1][sum-arr[i]];
            bool nt = dp[i-1][sum];
            dp[i][sum] = (t || nt);
        }
    }
    return dp[n-1][tar];
}

// Space Optimization
