                else if(tar==0) dp[i][tar] = 1;
                else dp[i][tar] =  (arr[i]==tar);
                continue;
            }
            int take = 0;
            if(arr[i] <= tar) take = dp[i-1][tar-arr[i]];
            int notake = dp[i-1][tar];
            dp[i][tar] =  (take+notake)%mod;
        }
    }
    return dp[n-1][sum];
