int countPartitions(int n, int d, vector<int>& arr) {
    int sum = 0, ans = 0;
    for(auto i:arr) sum += i;
    vector<vector<int>> dp(n, vector<int>(sum + 1, -1));
    for(int i = 0; i <= sum; i++){
