int fmemo(int i, int j, string &s, string &r, vector<vector<int>> &dp) {
    if (i < 0 || j < 0)
        return 0;

    if (dp[i][j] != -1)
        return dp[i][j];

    if (s[i] == r[j])
        return dp[i][j] = fmemo(i - 1, j - 1, s, r, dp) + 1;
    else
        return dp[i][j] = max(fmemo(i - 1, j, s, r, dp), fmemo(i, j - 1, s, r, dp));
